var s = env.get("LORALARM_CS_API");
var t = env.get("LORALARM_CS_API_TOKEN");
if (!s || s === "localhost:8080" || !t || t === "CHANGE_ME_TO_YOUR_CHIRPSTACK_API_TOKEN") {
    node.error("ChirpStack not configured! Fix: Menu -> Configuration Nodes -> global-config. Set LORALARM_CS_API and LORALARM_CS_API_TOKEN.");
    return null;
}
var p = (s.startsWith("http") ? "" : "http://") + s;
var h1 = {payload:{}, url:p + "/api/health", method:"GET", headers:{}};
var h2 = {payload:{}, url:p + "/api/applications", method:"GET", headers:{"Authorization": "Bearer " + t}};
return [h1, h2];

if (msg.statusCode === 200) {
    node.log("[OK] ChirpStack health check passed - server reachable");
    msg.payload = "Server: OK";
} else {
    node.error("[FAIL] ChirpStack health check failed: " + msg.statusCode + " - check server address");
    msg.payload = "Server: FAIL (" + msg.statusCode + ")";
}
msg.topic = "health";
return msg;

if (msg.statusCode === 200) {
    node.log("[OK] ChirpStack API auth passed - token valid");
    msg.payload = "Token: OK";
} else if (msg.statusCode === 401) {
    node.error("[FAIL] ChirpStack API auth failed: Invalid token. Set correct LORALARM_CS_API_TOKEN in global-config. This causes 'Enqueue error'.");
    msg.payload = "Token: FAIL (401 Invalid)";
} else if (msg.statusCode >= 400) {
    node.error("[FAIL] ChirpStack API auth failed: " + msg.statusCode + " - check server + token");
    msg.payload = "Token: FAIL (" + msg.statusCode + ")";
} else {
    msg.payload = "Token: Unknown (" + msg.statusCode + ")";
}
msg.topic = "auth";
return msg;

var s = env.get("LORALARM_CS_API");
var t = env.get("LORALARM_CS_API_TOKEN");
if (!s || s === "localhost:8080") {
    node.warn("[STARTUP] ChirpStack server WRONG! Currently: '" + (s || 'empty') + "'. Fix: Menu -> Configuration Nodes -> global-config -> LORALARM_CS_API = your-server:8080");
}
if (!t || t === "" || t === "CHANGE_ME_TO_YOUR_CHIRPSTACK_API_TOKEN") {
    node.warn("[STARTUP] ChirpStack API token NOT SET! Fix: Menu -> Configuration Nodes -> global-config -> LORALARM_CS_API_TOKEN = your JWT token. This causes 'Enqueue error'.");
}
return null;

var sensorConfig = global.get("sensorConfig") || {};
var settings = global.get("sensorSettings", "default") || {};
var changed = false;
Object.keys(sensorConfig).forEach(function(name) {
    if (!sensorConfig[name].hasSettings) return;
    var eui = sensorConfig[name].devEui;
    if (eui && !settings[eui]) {
        settings[eui] = { interrupt_threshold: null, acc_frequency: null, interrupt_duration: null };
        changed = true;
    }
});
if (changed) global.set("sensorSettings", settings, "default");
return null;

var app = (global.get("application") || {}).sublarm;
if (!app || String(msg.topic).split("/")[1] !== app) return null;

var devEui = msg.payload.deviceInfo && msg.payload.deviceInfo.devEui;
if (!devEui) return null;

var settings = global.get("sensorSettings", "default") || {};
var s = settings[devEui];
if (!s) return null;

var msgs = [];
if (s.interrupt_threshold) msgs.push({ payload: s.interrupt_threshold, fPort: "5", confirmed: "false", devEui: devEui });
if (s.acc_frequency) msgs.push({ payload: s.acc_frequency, fPort: "6", confirmed: "false", devEui: devEui });
if (s.interrupt_duration)  msgs.push({ payload: s.interrupt_duration,  fPort: "7", confirmed: "false", devEui: devEui });

if (msgs.length === 0) return null;
return [msgs];

var files = {"log_tx.csv": env.get("LORALARM_LOG_TX"), "log_alarms.csv": env.get("LORALARM_LOG_ALARMS")};
var allowed = Object.keys(files);
var f = msg.req.params.filename;
if (!Object.prototype.hasOwnProperty.call(files, f) || !files[f]) {
    msg.statusCode = 404;
    msg.headers = {"Content-Type": "text/plain"};
    msg.payload = "Unknown log file. Available: " + allowed.join(", ");
    return [null, msg];
}
msg.filename = files[f];
return [msg, null];

if (msg.error) {
    msg.statusCode = 404;
    msg.headers = {"Content-Type": "text/plain"};
    msg.payload = "Log file not found: " + (msg.error.message || "");
} else {
    var name = msg.req.params.filename;
    msg.headers = {
        "Content-Disposition": "attachment; filename=\"" + name + "\"",
        "Content-Type": "text/csv; charset=utf-8"
    };
    msg.statusCode = 200;
}
return msg;

var paths = [env.get("LORALARM_LOG_ALARMS"), env.get("LORALARM_LOG_TX")];
var dirs = [];
for (var i = 0; i < paths.length; i++) {
    var p = paths[i];
    if (!p) continue;
    var d = p.replace(/\/[^/]*$/, "");
    if (dirs.indexOf(d) === -1) dirs.push('"' + d + '"');
}
if (!dirs.length) return null;
msg.payload = dirs.join(" ");
return msg;
